from pathlib import Path
import json

BASE = Path(__file__).resolve().parent


def article(item_id, title, price, tags, intro, sections):
    paid = "\n\n".join(f"## {index}. {heading}\n{body}" for index, (heading, body) in enumerate(sections, 1))
    paid += "\n\n実行時は、まず対象を一つに絞って小さく試し、担当・期限・完了条件を記録してください。記録した結果を定期的に見直し、現場の規程や実情に合わせて項目と判断基準を更新することで、形だけの台帳になるのを防げます。"
    assert len(paid) > 900, (item_id, len(paid))
    return {"id": item_id, "title": title, "price": price, "tags": tags, "free": intro, "paid": paid}


def free(item_id, title, paired, tags, label, copy, accent, body):
    body += "\n\n最初から項目を増やしすぎず、現在進行中の1件で試してください。確認した日、担当、次に見る日を残し、実際に迷った点だけを次回のチェック項目へ追加すると運用が続きやすくなります。"
    assert len(body) >= 400, (item_id, len(body))
    return {"id": item_id, "title": title, "paired": paired, "tags": tags, "coverLabel": label, "coverCopy": copy, "accent": accent, "body": body}


def booth(item_id, title, price, tags, help_text, fields):
    assert len(fields) >= 8, item_id
    return {"id": item_id, "title": title, "price": price, "tags": tags, "help": help_text, "fields": fields}


